TLM.f("Tempora/Pasc0-4",{"officium":"Die V infra octavam Paschæ","rule":["ex Pasc0-0;","Credo","Sequentia","Suffr=Ecclesiæ,Papa;;"],"ruleInherited":["Sequentia","Credo","Prefatio=Pasch"],"fallback":"Tempora/Pasc0-0","sections":{"Introitus":[{"k":"ref","la":"Sap 10:20-21"},{"k":"text","la":"Victrícem manum tuam, Dómine, laudavérunt páriter, allelúja: quia sapiéntia apéruit os mutum, et linguas infántium fecit disértas, allelúja, allelúja."},{"k":"ref","la":"Ps 97:1"},{"k":"text","la":"Cantáte Dómino cánticum novum: quia mirabília fecit."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Victrícem manum tuam, Dómine, laudavérunt páriter, allelúja: quia sapiéntia apéruit os mutum, et linguas infántium fecit disértas, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui diversitátem géntium in confessióne tui nóminis adunásti: da, ut renátis fonte baptísmatis una sit fides méntium, et píetas actiónum."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolorum"},{"k":"ref","la":"Act 8:26-40"},{"k":"text","la":"In diébus illis: Angelus Dómini locútus est ad Philíppum, dicens: Surge et vade contra meridiánum ad viam, quæ descéndit ab Jerúsalem in Gazam: hæc est desérta. Et surgens ábiit. Et ecce vir Æthiops eunúchus, potens Candácis regínæ Æthíopum, qui erat super omnes gazas ejus, vénerat adoráre in Jerúsalem: et revertebátur sedens super currum suum, legénsque Isaíam Prophétam. Dixit autem Spíritus Philíppo: Accéde et adjúnge te ad currum istum. Accúrrens autem Philíppus, audívit eum legéntem Isaíam Prophétam, et dixit: Putásne, intéllegis, quæ legis? Qui ait: Et quómodo possum, si non áliquis osténderit mihi? Rogavítque Philíppum, ut ascénderet et sedéret secum. Locus autem Scriptúræ, quam legébat, erat hic: Tamquam ovis ad occisiónem ductus est: et sicut agnus coram tondénte se, sine voce, sic non apéruit os suum. In humilitáte judícium ejus sublátum est. Generatiónem ejus quis enarrábit, quóniam tollétur de terra vita ejus? Respóndens autem eunúchus Philíppo, dixit: Obsecro te, de quo Prophéta dicit hoc? de se, an de álio áliquo? Apériens autem Philíppus os suum, et incípiens a Scriptúra ista, evangelizávit illi Jesum. Et dum irent per viam, venérunt ad quandam aquam: et ait eunúchus: Ecce aqua, quid próhibet me baptizári? Dixit autem Philíppus: Si credis ex toto corde, licet. Et respóndens, ait: Credo, Fílium Dei esse Jesum Christum. Et jussit stare currum: et descendérunt utérque in aquam, Philíppus et eunúchus, et baptizávit eum. Cum autem ascendíssent de aqua, Spíritus Dómini rápuit Philíppum, et ámplius non vidit eum eunúchus. Ibat autem per viam suam gaudens. Philíppus autem invéntus est in Azóto, et pertránsiens evangelizábat civitátibus cunctis - donec veníret Cæsaréam - nomen Dómini Jesu Christi."}],"Graduale":[{"k":"ref","la":"Ps 117:24; 117:22-23"},{"k":"text","la":"Hæc dies, quam fecit Dóminus: exsultémus et lætémur in ea."},{"k":"text","la":"Lápidem, quem reprobavérunt ædificántes, hic factus est in caput ánguli: a Dómino factum est istud, et est mirábile in óculis nostris.","mark":"V"},{"k":"text","la":"Allelúja, allelúja,"},{"k":"text","la":"Surréxit Christus, qui creávit ómnia: et misértus est humáno géneri.","mark":"V"}],"Sequentia":[{"k":"text","la":"Víctimæ pascháli laudes ímmolent Christiáni."},{"k":"text","la":"Agnus rédemit oves: Christus ínnocens Patri reconciliávit peccatóres."},{"k":"text","la":"Mors et vita duéllo conflixére mirándo: dux vitæ mórtuus regnat vivus."},{"k":"text","la":"Dic nobis, María, quid vidísti in via?"},{"k":"text","la":"Sepúlcrum Christi vivéntis et glóriam vidi resurgéntis."},{"k":"text","la":"Angélicos testes, sudárium et vestes."},{"k":"text","la":"Surréxit Christus, spes mea: præcédet vos in Galilǽam."},{"k":"text","la":"Scimus Christum surrexísse a mórtuis vere: tu nobis, victor Rex, miserére. Amen. Allelúja."},{"k":"rubric","la":"Sequentia dicitur usque ad Sabbatum in Albis inclusive."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 20:11-18"},{"k":"text","la":"In illo témpore: María stabat ad monuméntum foris, plorans. Dum ergo fleret, inclinávit se et prospéxit in monuméntum: et vidit duos Angelos in albis, sedéntes, unum ad caput et unum ad pedes, ubi pósitum fúerat corpus Jesu. Dicunt ei illi: Múlier, quid ploras? Dicit eis: Quia tulérunt Dóminum meum: et néscio, ubi posuérunt eum. Hæc cum dixísset, convérsa est retrórsum, et vidit Jesum stantem: et non sciébat, quia Jesus est. Dicit ei Jesus: Múlier, quid ploras? quem quæris? Illa exístimans, quia hortulánus esset, dicit ei: Dómine, si tu sustulísti eum, dícito mihi, ubi posuísti eum: et ego eum tollam. Dicit ei Jesus: María. Convérsa illa, dicit ei: Rabbóni - quod dícitur Magíster. - Dicit ei Jesus: Noli me tángere, nondum enim ascéndi ad Patrem meum: vade autem ad fratres meos et dic eis: Ascéndo ad Patrem meum et Patrem vestrum, Deum meum et Deum vestrum. Venit María Magdaléne annúntians discípulis: Quia vidi Dóminum, et hæc dixit mihi."}],"Offertorium":[{"k":"ref","la":"Exod 13:5"},{"k":"text","la":"In die solemnitátis vestræ, dicit Dóminus, indúcam vos in terram fluéntem lac et mel, allelúja."}],"Secreta":[{"k":"text","la":"Súscipe, quǽsumus, Dómine, múnera populórum tuórum propítius: ut, confessióne tui nóminis et baptísmate renováti, sempitérnam beatitúdinem consequántur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"1 Pet 2:9"},{"k":"text","la":"Pópulus acquisitiónis, annuntiáte virtútes ejus, allelúja: qui vos de ténebris vocávit in admirábile lumen suum, allelúja."}],"Postcommunio":[{"k":"text","la":"Exáudi, Dómine, preces nostras: ut redemptiónis nostræ sacrosáncta commércia, et vitæ nobis cónferant præséntis auxílium, et gáudia sempitérna concílient."},{"k":"macro","name":"Per Dominum"}]},"hr":{"b6b52f51af7e4a66":{"t":"Mudr 10, 20-21, Ps 79, 1\nPobjednicu ruku tvoju Gospodine skupno su hvalili, <i>aleluja</i>,\njer je mudrost otvorila usta nijemima i učinila da govore i dječja usta, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 79, 1) Pjevajte Gospodinu pjesmu novu, jer je učinio divna djela.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Mudr 10, 20-21) Pobjednicu ruku tvoju Gospodine skupno su hvalili, <i>aleluja</i>,\njer je mudrost otvorila usta nijemima i učinila da govore i dječja usta, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Mudr. 10, 20, .21). Skupno su hvalili pobjednicu ruku Tvoju, Gospodine, aleluja; jer je mudrost otvorila usta nijemima i učinila, da govore i dječja usta, aleluja, aleluja. (Ps. 91, 1) Pjevajte G-ospodinu pjesmu novu, jer je učinio čudesne stvari. Slava Ocu . . . Skupno su . . , <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 310–311 (snimka 156) (OCR)"},"922fc44bf8c4f9f5":{"t":"<i>Pomolimo se</i>.\nBože, koji si različite narode sjedinio u priznanju svoga imena, daj da svi koji su preporođeni na zdencu krštenja isto vjeruju u duši i isto čine u svojim djelima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si različite narode sjedinio u priznanju svoga imena, podaj, da svi, koji su preporođeni vrutkom krštenja, isto vjieruju u duši i čime u svojim djelima, po G. n.","knRef":"Kniewald 1942, str. 310–311 (snimka 156) (OCR)"},"805997f221b66c93":{"t":"Dj 8, 26-40\nČitanje Djela apostolskih. U one dane anđeo Gospodnji reče Filipu: Ustani i idi prema jugu na put koji vodi od Jeruzalema u Gazu. On je pust. I ustade te pođe. I eto, Etiopljanin, dvoranin, mogućnik Kandake, kraljice etiopske, koji bijaše nad svim riznicama njezinim, došao je u Jeruzalem da se pokloni. Sad se vraćao kući, sjedio na kolima svojim i čitao Izaiju proroka. Duh reče Filipu: Idi i pristupi k ovim kolima! Kad Filip pritrči i ču gdje čita Izaiju proroka upita ga: Razumiješ li što čitaš? On odgovori: Kako bih mogao, ako me tko ne uputi? I zamoli Filipa da se popne i sjede s njime. A mjesto iz Pisma koje je čitao bijaše ovo: Vodi se kao janje na klanje. I ne otvara svojih usta kao ovca što je nijema pred onima koji je strigu. Izuzet je od zaštite i prava. I tko razmišlja o njegovu rodu? Jer je uklonjen od zemlje živih. Dvoranin upita Filipa: Molim te, za koga ovo govori prorok? Za sebe ili za koga drugoga? A Filip otvori usta svoja i počevši od ovoga mjesta Pisma propovijedi mu evanđelje o Isusu. Kad su išli putem, dođoše do nekakve vode i reče dvoranin: Evo vode, što brani meni da se krstim? Filip reče: Ako vjeruješ od svega srca, možeš. On odgovori: Vjerujem da je Isus Krist Sin Božji. I zapovjedi da stanu kola. I siđoše oba na vodu, Filip i dvoranin, i krsti ga. A kad iziđoše iz vode, Duh Gospodnji uze Filipa i više ga ne vidje dvoranin, nego radujući se otiđe putom svojim. Filip se nađe u Azotu i prolazeći propovijedao je ime Gospodina našega Isusa Krista svim gradovima dok ne dođe u Cezareju.","kn":"Čitanje Djela Apostolskih (8, 26-40). U onim danima anđeo Gospodnji reče Filipu; Ustani i idi prema, jugu na put, koji vodi od Jeruzalema u Gazui; on je pust. I ustade, te pođe. I eto, Etiopljanin, dvoranin, mo-gućnik Kandake, kraljice Etiopske, koji bijaše nad svim rizniicama njezinim, došao je u Jeruzalem, da se pokloni. Sad se vraćao kući, sjedio na kolima, svojim, i čitao Izaiju proroka. Duh reče Filipu:. Idi i’ pristupi k ovim kolima! Kad Filip pritrči 1 ču gdje čita Izaiju proroka, upita ga; Razumiješ li što čitaš? On odgovori: A kako bih mogao, ako me tko ne uputi? I zamoli Filipa, da, se popne i sjetoe s njime. A mjesto iz Pisma, koje je čitao, bijaše ovo: »Vodi se kao janje na klanje. I ne otvara svojih usta, kao ovca, što je nijema pred onima, koji je strigu. Izuzet je od zaštite i prava. I tko razmišlja o njegovu rodu? Jer je odlučen od zemlje živih«.. Dvoranin upita Filipa: Molim te, za koga ovo govori, prorok? Za sebe ili za koga drugoga? A Filip otvorivši usta svoja 1 počevši od ovoga mjesta Pisma propovijedi . mu evanđelje o Isusu. Kad; su išli putem, dođoše do nekakve vode i.reče dvoranin: Evo vode, što brani meni, da.se krstim?. (Filip reče: Ako vjeruješ .od svega srca, možeš. On odigovori;. Vjerujem, da je Isus Krist Sin Božji). I zapovjedi, da stanu kola, i siđoše oba na vodu, Filip i dvoranin, i krsti ga. A kad iziđoše iz vode. Duh Gospodnji uze Filipa, i više ga ne vidje dvoranin; nego radujući se otide putem svojim. A Filip se nađe u Azotu, i prolazeći propovijedao je ime G. N. I. K. svim gradovima, dok ne dođe u Cezareju.","knRef":"Kniewald 1942, str. 310–311 (snimka 156) (OCR)"},"5d28775841860ee8":{"t":"Ps 117, 24 i 22-23\nOvo je dan što ga učini Gospodin. Kličimo i radujmo se danas! Kamen koji odbaciše zidari posta glava od ugla. To je učinio Gospodin i divno je u očima našim.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nUskrsnuo je Krist koji je sve stvorio i smilovao se ljudskom rodu.","kn":"(Ps. 117, 24;. 22, 23).. Ovo je dan, koji nam. je pripra.vio Gospodin, kličiimo. i rađujmo se. Kamen, koji odbaclše zidari, po;sta glava od ugla: to je učinio Gospodin i divno je u očima našim.\n\nAleluja, aleluja. Uskrsnuo je Krist, koji je šve stvorio i smilovao se rodu ljudskomu.","knRef":"Kniewald 1942, str. 310–311 (snimka 156) (OCR)"},"a670bd50efcad44c":{"t":"Svetoj Žrtvi uskrsnici dajte slavu krštenici!<i>\n</i>\nJanje ovce oslobodi Krist nas grješne preporodi.<i>\n</i>\nSa životom smrt se sasta i čudesna borba nasta: Vođa živih pade tada i živ živcat opet vlada.<i>\n</i>\nMarijo, o reci što je? Što ti oko vidjelo je?<i>\n</i>\nGrob ja vidjeh Krista Boga, svijetlu slavu uskrsloga.<i>\n</i>\nAnđele i platno bijelo u kom bješe sveto tijelo.<i>\n</i>\nUfanje mi uskrslo je Krist, moj Gospod i sve moje! Pred vama će tamo gdje je cvjetna strana Galileje.<i>\n</i>\nZnamo da si doistine uskrsnuo Božji Sine! Pobjedniče, Kralju divan, budi nama milostivan!<i>\n</i>\n<i>amen</i>, <i>aleluja</i>."},"58a3963e59b5d50c":{"t":"Iv 20, 11-18\nSlijedi sveto Evanđelje po Ivanu. U ono je vrijeme Marija Magdalena stajala na polju kod groba i plakala. Dok je dakle plakala, sagnu se prema grobu i vidje dva anđela gdje sjede u bijelim haljinama, jedan povrh glave a drugi podno nogu gdje je ležalo tijelo Isusovo. Oni je zapitaju: Ženo, što plačeš? Odgovori im: Uzeše Gospodina mojega i ne znam kamo ga položiše. Rekavši ovo, obazre se natrag i vidi Isusa gdje stoji a nije znala da je Isus. Reče joj Isus: Ženo, što plačeš? Koga tražiš? Ona misleći da je vrtlar reče mu: Gospodine, ako si ga ti uzeo, kaži mi gdje si ga metnuo, i ja ću ga uzeti. Reče joj Isus: Marijo! A ona obazrevši se kaže mu hebrejski: Rabboni (to znači: Učitelju moj!) Veli joj Isus: Ne diraj me jer još nisam uzašao k Ocu svome, nego idi k mojoj braći i reci im: Uzlazim k Ocu svome i k Ocu vašemu. I otiđe Marija Magdalena i javi učenicima: Vidjela sam Gospodina i ovo mi je rekao.","kn":"t Slijedi sv. evanđelje po Ivanu (20, 11-18). U ono je vrijeme Marija Magdalena stajala napolju kod groba i plakala. Dok je dakle plakala,, sagnu se prema grobu, i vidje dva anđela gdje sjede u bijelim haljinama, jedan povrh glave, a drugi podno nogu, gdje je ležalo tijelo Isusovo. Oni joj kažu: Ženo, što plačeš?. Kaže im: Uzeše Gospodina mojega, i ne znam,' kamo ga položiše. Rekavši ovo, obazre se natrag i vidi Isusa, gdje stoji, a nij© znala da je Isus. Kaže joj Isus: Ženo, što plačeš? koiga tražiš? Ona misleći, da je vrtljar, kaže mu: Gospodine, ako si ga ti uzeoi, kaži mi, gdje si ga naetnuo, i ja ću ga uzeti. Kaže joj Isus: Marijol A ona obazrevši se kaže mu hebrejski Rabbomi (to znači; Učitelju moj!). Kaže joj\" ISus: Ne drži me čvrsto, jer još nisam uzašao k Ocu svome, negoi idi k mojoj braćii i reci lm: Uzlazim k Ocu svome 1 k Ocu vašemu. I otide Marija Magdalena i javi učenitcima: Vidjela sam Gospodina i ovo mi je rekao.","knRef":"Kniewald 1942, str. 310–311 (snimka 156) (OCR)"},"f163a778d1e65bcf":{"t":"Izl 13, 5\nU dan vaše svečanosti, veli Gospodin, uvest ću vas u zemlju kojom teče mlijeko i med, <i>aleluja</i>.","kn":"(Izl. 13, 5). U dan svečani, veli Gospodin, uvest ću vas u zemlju, kojom teče mlijeko, i med, aleluja.","knRef":"Kniewald 1942, str. 312–313 (snimka 157) (OCR)"},"e7651a0148e96a18":{"t":"Primi milostivo, molimo, Gospodine, darove svoga puka da obnovljen priznanjem tvoga imena i krštenjem dostigne vječno blaženstvo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi milostivo, molimo. Gospodine, darove svojih naroda, da obnovljeni priznanjem Tvoga imena i krštenjem, dostignu vječno blaženstvo, po G. n.","knRef":"Kniewald 1942, str. 312–313 (snimka 157) (OCR)"},"687cae1ead8b8c38":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>danas</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"496fa9646b691c63":{"t":"1 Pt 2, 9\nPuče stečeni, naviještajte snagu onoga, <i>aleluja</i>,\nkoji vas pozva iz tame k divnom svjetlu svojemu, <i>aleluja</i>.","kn":"(I. Petr. 2, 9). Puče stečeni, navdještaj kreposti onoga, aleluja, koji vas pozva iz tame k divnom svijetlu svojemu, aleluja.","knRef":"Kniewald 1942, str. 312–313 (snimka 157) (OCR)"},"fa5f79c7d850d255":{"t":"<i>Pomolimo se</i>.\nUsliši, Gospodine, naše molitve, da nam presveti darovi našeg otkupljenja pruže pomoć za sadašnji život i uvedu nas u vječne radosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Usldiši, Gospodine, naše molitve, da nam presveti darovi našeg otkupljenja pruže pomoć za sadašnji život i, uvedu nas u vječne radosti, I>o G. n.","knRef":"Kniewald 1942, str. 312–313 (snimka 157) (OCR)"}}});
